function row(id:string,text:string,date=DAY,version=1){return {id:`server-${id}`,client_entry_id:id,entry_date:date,received_at:`${date}T12:00:00Z`,content_version:version,blob:encryptEntry({dataKey:KEY},USER,id,text,date,null,undefined,version).blobB64};}
function nativeResponse(url:string,body:unknown,headers:Record<string,string>={},status=200){const response=new Response(JSON.stringify(body),{status,headers:{"Content-Type":"application/json",...headers}});Object.defineProperty(response,"url",{value:url});return response;}
function transport(entries:ReturnType<typeof row>[]){vi.stubGlobal("fetch",async(url:string)=>{const path=new URL(url).pathname;if(path.endsWith("/entries"))return nativeResponse(url,entries,{"X-Entries-Revision":"1"});if(path.endsWith("/insights"))return nativeResponse(url,{active_days:5});if(path.endsWith("/meta"))return nativeResponse(url,{unlock_days:30});return nativeResponse(url,{});});}
async function mount(navigation:any={navigate:()=>undefined},provider=false){await act(async()=>{root=ReactTestRenderer.create(provider?<SessionProvider><HistoryScreen navigation={navigation}/></SessionProvider>:<HistoryScreen navigation={navigation}/>);});await flush();return root!;}
async function flush(){await act(async()=>{for(let i=0;i<80;i++)await Promise.resolve();});}
function text(){return root!.root.findAllByType(Text).map(n=>n.props.children).flat(Infinity).filter(x=>typeof x==="string"||typeof x==="number").join(" ");}
async function press(label:string){const button=root!.root.findAllByType(TouchableOpacity).find(n=>n.props.accessibilityLabel===label);if(!button)throw new Error(`missing public button ${label}: ${text()}`);if(button.props.disabled)throw new Error(`disabled public button ${label}`);await act(async()=>{void button.props.onPress();});await flush();}
async function refresh(){await act(async()=>{void root!.root.findByType(FlatList).props.refreshControl.props.onRefresh();});await flush();}
async function chooseAlert(label:string){const buttons=Alert.alert.mock.lastCall?.[2] as Array<{text:string;onPress?:()=>void}>|undefined;const button=buttons?.find(item=>item.text===label);if(!button)throw new Error(`missing native alert choice ${label}`);await act(async()=>button.onPress?.());await flush();}
function navigation(){const listeners=new Map<string,Set<()=>void>>();return {navigate:vi.fn(),addListener(event:string,callback:()=>void){const group=listeners.get(event)??new Set();group.add(callback);listeners.set(event,group);return()=>group.delete(callback);},async focus(){await act(async()=>listeners.get("focus")?.forEach(callback=>callback()));await flush();},async blur(){await act(async()=>listeners.get("blur")?.forEach(callback=>callback()));await flush();}};}
