 for(const end of ["stop","unmount","vault lock","native play failure"]as const)it(`native recording and its physical scratch custody end on ${end}`,async()=>{
  const original=Object.assign(row("entry-play","Native recording writing"),{audio:{attachment_id:"att-native",expires_at:"2027-10-29T00:00:00Z"}}),audio=Buffer.from("native recording bytes");
  const players:Array<{uri:string;playing:boolean;released:boolean}>=[];
  vi.mocked(createAudioPlayer).mockImplementation(((source:{uri:string})=>{const state={uri:source.uri,playing:false,released:false};players.push(state);return {play(){if(end==="native play failure")throw new Error("native player unavailable");state.playing=true;},release(){state.playing=false;state.released=true;}};}) as unknown as typeof createAudioPlayer);
  vi.stubGlobal("fetch",async(url:string)=>new URL(url).pathname.includes("/audio/attachments/")?nativeResponse(url,{blob:encryptAudio({dataKey:KEY},USER,original.client_entry_id,audio).blobB64,mime_type:"audio/m4a",duration_seconds:4}):nativeResponse(url,[original],{"X-Entries-Revision":"1"}));
  await mount();await press("Play recording");expect(players.length).toBe(1);const player=players[0]!;
  if(end!=="native play failure"){expect(player.playing).toBe(true);expect(Buffer.from(await files.readAsStringAsync(player.uri),"base64")).toEqual(audio);}
  if(end==="stop")await press("Stop playback");else if(end==="unmount")await act(async()=>{root!.unmount();root=undefined;});else if(end==="vault lock")await act(async()=>vault.lock());
  await flush();expect(player.playing).toBe(false);expect(player.released).toBe(true);expect(files.__hasFile(player.uri)).toBe(false);
 });
